using System.Transactions;

using (var outer = new TransactionScope())
{
    var outerId = Transaction.Current!.TransactionInformation.LocalIdentifier;

    using (new TransactionScope(TransactionScopeOption.Suppress))
        Console.WriteLine("suppress: " + (Transaction.Current is null));

    using (new TransactionScope(TransactionScopeOption.RequiresNew))
        Console.WriteLine("requiresNew same tx: " + (Transaction.Current!.TransactionInformation.LocalIdentifier == outerId));

    using (new TransactionScope(TransactionScopeOption.Required))
        Console.WriteLine("required same tx: " + (Transaction.Current!.TransactionInformation.LocalIdentifier == outerId));
}

