foreach (var u in Map<User>(table.CreateDataReader()))
    Console.WriteLine($"{u.Id}|{u.DisplayName ?? "(null)"}|{u.Email ?? "(null)"}");

static List<T> Map<T>(DbDataReader reader) where T : new()
{
    var props = typeof(T).GetProperties().ToDictionary(p => p.Name, StringComparer.OrdinalIgnoreCase);
    var list = new List<T>();
    while (reader.Read())
    {
        var item = new T();
        for (int i = 0; i < reader.FieldCount; i++)
            if (props.TryGetValue(reader.GetName(i), out var p))
                p.SetValue(item, reader.IsDBNull(i) ? null : reader.GetValue(i));
        list.Add(item);
    }
    return list;
}

